const input = $input.first().json || {};

function compactJson(value) {
  try {
    return JSON.stringify(value, null, 2);
  } catch (error) {
    return String(value);
  }
}

function fail({ code, message, details = [] }) {
  return [
    {
      json: {
        stop_before_http: true,
        success: false,
        component_id: "C4-D",
        component_version: "v1",
        event_id: input.input?.event_id || null,
        event_type: input.input?.event_type || null,
        content_draft: null,
        c4m_handoff: null,
        source_result: input.input || {},
        error: {
          code,
          message,
          details
        },
        next_action: "route_to_failure_log"
      }
    }
  ];
}

if (!input || Object.keys(input).length === 0) {
  return fail({
    code: "EMPTY_INPUT",
    message: "Input object is empty."
  });
}

if (!input.input || typeof input.input !== "object") {
  return fail({
    code: "MISSING_INPUT_OBJECT",
    message: "Input must include an input object."
  });
}

const source = input.input;
const config = input.config || {};

if (source.success !== true) {
  return fail({
    code: "UPSTREAM_ACTION_FAILED",
    message: "C4-D will not generate content draft when upstream action failed.",
    details: [
      {
        upstream_component: source.component_id || null,
        upstream_error: source.error || null
      }
    ]
  });
}

if (source.next_action !== "generate_content_draft") {
  return fail({
    code: "CONTENT_GENERATION_NOT_REQUESTED",
    message: "source.next_action is not generate_content_draft.",
    details: [{ next_action: source.next_action || null }]
  });
}

if (!config.content_type) {
  return fail({
    code: "MISSING_CONTENT_TYPE",
    message: "config.content_type is required."
  });
}

if (!config.platform) {
  return fail({
    code: "MISSING_PLATFORM",
    message: "config.platform is required."
  });
}

if (!config.content_goal) {
  return fail({
    code: "MISSING_CONTENT_GOAL",
    message: "config.content_goal is required."
  });
}

if (!config.client_ai_profile || typeof config.client_ai_profile !== "object") {
  return fail({
    code: "MISSING_CLIENT_AI_PROFILE",
    message: "config.client_ai_profile is required."
  });
}

if (!config.client_ai_profile.client_profile || !config.client_ai_profile.content_rules) {
  return fail({
    code: "INCOMPLETE_CLIENT_AI_PROFILE",
    message: "client_ai_profile must include at least client_profile and content_rules."
  });
}

const payload = source.payload || {};
const contentBrief =
  payload.content_brief ||
  payload.brief ||
  payload.topic ||
  "";

if (!contentBrief || !String(contentBrief).trim()) {
  return fail({
    code: "MISSING_CONTENT_BRIEF",
    message: "input.payload.content_brief, brief, or topic is required."
  });
}

if (!config.llm || typeof config.llm !== "object") {
  return fail({
    code: "MISSING_LLM_CONFIG",
    message: "config.llm is required."
  });
}

if (!config.llm.provider || !config.llm.endpoint || !config.llm.model) {
  return fail({
    code: "INCOMPLETE_LLM_CONFIG",
    message: "config.llm must include provider, endpoint, and model."
  });
}

if (config.llm.provider !== "groq") {
  return fail({
    code: "UNSUPPORTED_LLM_PROVIDER",
    message: "C4-D v1 demo supports provider = groq.",
    details: [{ provider: config.llm.provider }]
  });
}

const profile = config.client_ai_profile;
const contentRules = profile.content_rules || {};
const voiceProfile = profile.voice_profile || {};
const riskBoundaries = profile.risk_boundaries || {};
const approvalRules = profile.approval_rules || {};

const enabledTypes = Array.isArray(contentRules.enabled_content_types)
  ? contentRules.enabled_content_types
  : [];

if (enabledTypes.length > 0 && !enabledTypes.includes(config.content_type)) {
  return fail({
    code: "CONTENT_TYPE_NOT_ENABLED",
    message: "config.content_type is not enabled in client content rules.",
    details: [
      {
        content_type: config.content_type,
        enabled_content_types: enabledTypes
      }
    ]
  });
}

const systemInstruction = [
  "You are a client-configured AI content drafting component inside an automation workflow.",
  "You generate drafts only. You do not publish content.",
  "Use only the provided content brief, source context, and client AI profile.",
  "Follow the client's voice, content rules, platform rules, forbidden claims, and approval rules.",
  "Do not invent facts, case studies, testimonials, statistics, external claims, pricing, revenue, guarantees, or urgency.",
  "If the user requests a prohibited claim, rewrite safely and add a risk flag.",
  "Return valid JSON only. Do not include markdown fences."
].join(" ");

const outputSchema = {
  content_draft: {
    title: "string",
    body: "string",
    platform: config.platform,
    content_type: config.content_type,
    cta: "string",
    sections: ["string"],
    claims_used: ["string"],
    personalization_used: ["string"],
    assumptions: ["string"],
    risk_flags: ["string"],
    approval_required: true
  }
};

const userContent = [
  "CONTENT TASK",
  compactJson({
    content_type: config.content_type,
    platform: config.platform,
    content_goal: config.content_goal,
    default_next_action: config.default_next_action || "package_draft_for_approval"
  }),
  "",
  "CONTENT BRIEF",
  String(contentBrief),
  "",
  "SOURCE CONTEXT",
  compactJson({
    topic: payload.topic || null,
    source_context: payload.source_context || null,
    source: payload.source || null,
    metadata: source.metadata || null
  }),
  "",
  "CLIENT AI PROFILE",
  compactJson(profile),
  "",
  "CONTENT RULES TO ENFORCE",
  compactJson({
    enabled_content_types: enabledTypes,
    preferred_tone: contentRules.preferred_tone || [],
    preferred_length: contentRules.preferred_length || "",
    preferred_structure: contentRules.preferred_structure || "",
    topics_allowed: contentRules.topics_allowed || [],
    topics_avoided: contentRules.topics_avoided || [],
    cta_style: contentRules.cta_style || "",
    external_claims_allowed: contentRules.external_claims_allowed === true,
    platform_rules: contentRules.platform_rules || {},
    voice_style: voiceProfile.style || "",
    phrases_to_use: voiceProfile.phrases_to_use || [],
    phrases_to_avoid: voiceProfile.phrases_to_avoid || [],
    forbidden_claims: riskBoundaries.forbidden_claims || [],
    manual_review_triggers: riskBoundaries.manual_review_triggers || [],
    approval_policy: approvalRules.default_policy || "approval_required_before_external_action"
  }),
  "",
  "OUTPUT JSON SCHEMA",
  compactJson(outputSchema),
  "",
  "Return JSON only with the key content_draft."
].join("\n");

const body = {
  model: config.llm.model,
  messages: [
    {
      role: "system",
      content: systemInstruction
    },
    {
      role: "user",
      content: userContent
    }
  ],
  temperature: config.llm.temperature ?? 0.4,
  max_tokens: config.llm.max_tokens ?? 1000,
  response_format: {
    type: "json_object"
  }
};

return [
  {
    json: {
      stop_before_http: false,
      request: {
        provider: config.llm.provider,
        endpoint: config.llm.endpoint,
        body
      },
      context: {
        component_id: "C4-D",
        component_version: "v1",
        event_id: source.event_id || null,
        event_type: source.event_type || null,
        content_type: config.content_type,
        platform: config.platform,
        content_goal: config.content_goal,
        client_ai_profile: profile,
        source_result: source,
        next_action: config.default_next_action || "package_draft_for_approval"
      }
    }
  }
];

const llmOutput = $input.first().json || {};
const prepared = $("Prepare Content Generation Request").first().json;
const context = prepared.context;

const content =
  llmOutput.choices?.[0]?.message?.content ??
  llmOutput.choices?.[0]?.text ??
  null;

let parsedJson = null;
let parseError = null;

if (content) {
  try {
    parsedJson = JSON.parse(content);
  } catch (error) {
    parseError = error.message;
  }
}

const contentDraft = parsedJson?.content_draft || null;

if (!contentDraft) {
  return [
    {
      json: {
        success: false,
        component_id: context.component_id,
        component_version: context.component_version,
        event_id: context.event_id,
        event_type: context.event_type,
        content_draft: null,
        c4m_handoff: null,
        source_result: context.source_result,
        error: {
          code: parseError ? "CONTENT_DRAFT_PARSE_FAILED" : "MISSING_CONTENT_DRAFT",
          message: parseError
            ? "LLM response could not be parsed as JSON."
            : "LLM response did not include content_draft.",
          details: [{ raw_content: content, parse_error: parseError }]
        },
        next_action: "route_to_failure_log"
      }
    }
  ];
}

const riskFlags = Array.isArray(contentDraft.risk_flags)
  ? contentDraft.risk_flags
  : [];

const normalizedDraft = {
  title: contentDraft.title || `${context.content_type} draft`,
  body: contentDraft.body || "",
  platform: contentDraft.platform || context.platform,
  content_type: contentDraft.content_type || context.content_type,
  cta: contentDraft.cta || "",
  sections: Array.isArray(contentDraft.sections) ? contentDraft.sections : [],
  claims_used: Array.isArray(contentDraft.claims_used) ? contentDraft.claims_used : [],
  personalization_used: Array.isArray(contentDraft.personalization_used) ? contentDraft.personalization_used : [],
  assumptions: Array.isArray(contentDraft.assumptions) ? contentDraft.assumptions : [],
  risk_flags: riskFlags,
  approval_required: true,
  provider: prepared.request.provider,
  model: prepared.request.body.model,
  usage: llmOutput.usage || null,
  finish_reason: llmOutput.choices?.[0]?.finish_reason || null
};

const draftTitle = normalizedDraft.title;
const draftSummary = `Content draft generated for ${normalizedDraft.content_type} on ${normalizedDraft.platform}: ${draftTitle}`;

const c4mHandoff = {
  next_component: "C4-M",
  input: {
    success: true,
    component_id: "C4-D",
    component_version: "v1",
    event_id: context.event_id,
    event_type: "ai_content_draft",
    ai_result: {
      provider: prepared.request.provider,
      model: prepared.request.body.model,
      task_type: "content_draft",
      status: "completed",
      content,
      parsed_json: {
        draft_title: draftTitle,
        draft_summary: draftSummary,
        content_type: normalizedDraft.content_type,
        platform: normalizedDraft.platform,
        content_title: normalizedDraft.title,
        content_body: normalizedDraft.body,
        cta: normalizedDraft.cta,
        sections: normalizedDraft.sections,
        claims_used: normalizedDraft.claims_used,
        assumptions: normalizedDraft.assumptions,
        risk_flags: normalizedDraft.risk_flags,
        human_approval_required: true
      },
      usage: llmOutput.usage || null,
      finish_reason: llmOutput.choices?.[0]?.finish_reason || null
    },
    source_result: context.source_result,
    error: null,
    next_action: "request_approval"
  },
  config: {
    draft_type: "content",
    draft_status: "needs_review",
    approval_type: "content_review",
    reviewer_email: context.client_ai_profile?.approval_rules?.primary_reviewer_email || "shwetabh.singh@lexnovahq.com",
    owner: "marketing",
    priority: riskFlags.length ? "high" : "normal",
    default_next_action: "request_approval"
  }
};

return [
  {
    json: {
      success: true,
      component_id: context.component_id,
      component_version: context.component_version,
      event_id: context.event_id,
      event_type: context.event_type,
      content_draft: normalizedDraft,
      c4m_handoff: c4mHandoff,
      source_result: context.source_result,
      error: null,
      next_action: context.next_action
    }
  }
];

const prepared = $input.first().json || {};

return [
  {
    json: {
      success: prepared.success,
      component_id: prepared.component_id,
      component_version: prepared.component_version,
      event_id: prepared.event_id,
      event_type: prepared.event_type,
      content_draft: prepared.content_draft,
      c4m_handoff: prepared.c4m_handoff,
      source_result: prepared.source_result,
      error: prepared.error,
      next_action: prepared.next_action
    }
  }
];
